import{_ as r,a as e,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 57 巽：温和进入，也须明确行动至59 涣：散开阻滞，再寻共同依托","description":"从巽兑的沟通读到涣节的尺度、中孚的信实与既济未济的开放结尾，逐爻核对古籍。","frontmatter":{"title":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 57 巽：温和进入，也须明确行动至59 涣：散开阻滞，再寻共同依托","description":"从巽兑的沟通读到涣节的尺度、中孚的信实与既济未济的开放结尾，逐爻核对古籍。","splitFrom":"life/personal/yijing/hexagrams-57-64.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济","summary":"从巽兑的沟通读到涣节的尺度、中孚的信实与既济未济的开放结尾，逐爻核对古籍。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济","link":"/life/personal/yijing/hexagrams-57-64"},"next":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 60 节：尺度应使生活可持续至62 小过：在有限处适度加厚","link":"/life/personal/yijing/hexagrams-57-64-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济","link":"/life/personal/yijing/hexagrams-57-64"},"next":{"text":"六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 60 节：尺度应使生活可持续至62 小过：在有限处适度加厚","link":"/life/personal/yijing/hexagrams-57-64-part-02"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-57-64-part-01.md","filePath":"life/personal/yijing/hexagrams-57-64-part-01.md"}'),n={name:"life/personal/yijing/hexagrams-57-64-part-01.md"};function d(s,t,i,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="六十四卦详读-五十七至六十四-巽、兑、涣、节、中孚、小过、既济、未济-·-57-巽-温和进入-也须明确行动至59-涣-散开阻滞-再寻共同依托" tabindex="-1">六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 57 巽：温和进入，也须明确行动至59 涣：散开阻滞，再寻共同依托 <a class="header-anchor" href="#六十四卦详读-五十七至六十四-巽、兑、涣、节、中孚、小过、既济、未济-·-57-巽-温和进入-也须明确行动至59-涣-散开阻滞-再寻共同依托" aria-label="Permalink to &quot;六十四卦详读（五十七至六十四）：巽、兑、涣、节、中孚、小过、既济、未济 · 57 巽：温和进入，也须明确行动至59 涣：散开阻滞，再寻共同依托&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-57-64">返回分篇目录</a></p><p>本篇完成六十四卦的最后一组。每卦先列<strong>经文原文</strong>，再列现代简释；<strong>大象</strong>来自《象传》，主要古注依据为王弼注、孔颖达疏《周易正义》。引文保留古代字形与占筮判断，现代概括不作为预测方法。个别电子本文字不同，采用哪种写法会就地注明。</p><p>这组可从四条线索进入：巽与兑的传达和相悦，涣与节的散释和限制，中孚与小过的信实和分寸，既济与未济的完成和未完成。不要先给整卦贴上“好卦、坏卦”标签，再忽略其中相反的爻辞。</p><h2 id="六十四卦详读-五十七至六十四" tabindex="-1">六十四卦详读（五十七至六十四） <a class="header-anchor" href="#六十四卦详读-五十七至六十四" aria-label="Permalink to &quot;六十四卦详读（五十七至六十四） {#六十四卦详读-五十七至六十四}&quot;">​</a></h2><p>本篇完成六十四卦的最后一组。每卦先列<strong>经文原文</strong>，再列现代简释；<strong>大象</strong>来自《象传》，主要古注依据为王弼注、孔颖达疏《周易正义》。引文保留古代字形与占筮判断，现代概括不作为预测方法。个别电子本文字不同，采用哪种写法会就地注明。</p><p>这组可从四条线索进入：巽与兑的传达和相悦，涣与节的散释和限制，中孚与小过的信实和分寸，既济与未济的完成和未完成。不要先给整卦贴上“好卦、坏卦”标签，再忽略其中相反的爻辞。</p><h2 id="gua-57" tabindex="-1">57 巽：温和进入，也须明确行动 <a class="header-anchor" href="#gua-57" aria-label="Permalink to &quot;57 巽：温和进入，也须明确行动 {#gua-57}&quot;">​</a></h2><p><strong>卦符：䷸｜上卦巽 ☴，下卦巽 ☴，风相随而至。</strong>“巽”读 xùn，有顺、入的含义。《正义》以卑顺为体、容入为用，解释风无所不入与人事谦顺的联系。</p><p><strong>卦辞原文：</strong></p><blockquote><p>巽：小亨。利有攸往。利見大人。</p></blockquote><p><strong>白话概括：</strong> 谦顺可以获得有限通达，利于行动与求见有德有能者；但全靠顺从，所通仍有限。《正义》特别说明命令如果本身不可从，即使上下都讲巽，也不能真正获得支持。这保留了判断内容的必要性。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>進退，利武人之貞。</td><td>犹疑进退，需要武人的坚定与纪律；不是建议用强制解决所有犹豫，而是补足行动上的稳定性。</td></tr><tr><td>九二</td><td>巽在牀下，用史巫紛若，吉无咎。</td><td>姿态极低，以史巫事神；《正义》区别敬神与屈从人间威势，并以居中解释其吉，现代不必复制祭告仪式。</td></tr><tr><td>九三</td><td>頻巽，吝。</td><td>“频”可按反复理解，《正义》则释为频蹙忧戚、不得已屈从；两说都不能把形式低姿态直接等同有效沟通。</td></tr><tr><td>六四</td><td>悔亡，田獲三品。</td><td>狩猎有所获，古注以实际功效解释；“三品”涉及猎物用途或类别，不是三个奖项的预告。</td></tr><tr><td>九五</td><td>貞吉悔亡，无不利。无初有終，先庚三日，後庚三日，吉。</td><td>开端未善仍可修正成终；《正义》将“庚”释为申命，强调先后重申、避免突然施行，不据此确定现实办事日期。</td></tr><tr><td>上九</td><td>巽在牀下，喪其資斧，貞凶。</td><td>同样低在床下，却因过度卑屈失去资具与决断能力；与九二同象异断，须看所处条件。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>隨風，巽；君子以申命行事。</p></blockquote><p><strong>大象解释：</strong> 风相随而至，命令需反复申明并落实行动。“申”是重申，不能只不断重复口号而不说明做法与责任。</p><p><strong>整体读法与误区：</strong> 巽既肯定谦顺，也写进退、频巽和丧资斧，显出谦逊与失去主体判断之间的界线。现代可用于观察沟通：要求是否明白，是否允许反馈，反复解释是否带来行动。九二与上九的对照尤其提醒，同一种姿态在不同位置可能产生相反结果；不能以“巽为风”便把性格、职业和命运固定化。</p><p><strong>经传对读：</strong> 三爻的频巽与九五前后三日的反复并不相同：前者显示屈从的困境，后者通过反复申命求审慎。四爻以田猎所得检验实效，大象也将申命与行事连写，提醒传达必须落到事情上。可以比较一项要求是越说越模糊，还是经反馈越来越明确，借此理解柔顺中仍需有主见。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B7%BD" target="_blank" rel="noopener noreferrer">《周易·巽》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E5%B7%BD" target="_blank" rel="noopener noreferrer">《周易正义》卷六·巽</a>。</p><h2 id="gua-58" tabindex="-1">58 兑：相悦以信实为根基 <a class="header-anchor" href="#gua-58" aria-label="Permalink to &quot;58 兑：相悦以信实为根基 {#gua-58}&quot;">​</a></h2><p><strong>卦符：䷹｜上卦兑 ☱，下卦兑 ☱，两泽相连。</strong> 兑取悦义，古文“说”在此读 yuè；泽的润养使万物悦，是传文及古注的联系。</p><p><strong>卦辞原文：</strong></p><blockquote><p>兌：亨。利貞。</p></blockquote><p><strong>白话概括：</strong> 相悦可以通达，但须合于正当。《正义》担心取悦落入谄媚，又担心只讲刚正变成暴厉，因此以刚在内、柔在外说明平衡。它不是圆滑讨好教程，也不要求言语永远让人舒服。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>和兌，吉。</td><td>和悦而无私党牵系，关系自然；“和”不是遇见争议就回避原则。</td></tr><tr><td>九二</td><td>孚兌，吉，悔亡。</td><td>建立在信实上的喜悦，可减少悔恨；好听与可信有联系，却不能混为一谈。</td></tr><tr><td>六三</td><td>來兌，凶。</td><td>不当位置上主动求悦，可能成为迎合；古注据其不中不正解释，不是一切主动社交都有凶。</td></tr><tr><td>九四</td><td>商兌，未寧，介疾有喜。</td><td>衡量怎样相悦，尚未安定；能辨别、隔开有害因素才有喜。“商”有商度义，勿作商业占验。</td></tr><tr><td>九五</td><td>孚于剝，有厲。</td><td>信任了会侵蚀自身正当性的对象，便有危险；可见“有孚”也要审查所信的内容。</td></tr><tr><td>上六</td><td>引兌。</td><td>以引诱、牵引求悦，爻辞未直写吉凶，《小象》说“未光”；不宜自行补成“必大凶”。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>麗澤，兌；君子以朋友講習。</p></blockquote><p><strong>大象解释：</strong>“丽”在古注中是相连，两泽互润，朋友通过讲论与习行互相增益。讨论的价值包括指正和共同练习，不只是彼此称赞。</p><p><strong>整体读法与误区：</strong> 比较“和兑、孚兑、来兑、引兑”，会看到悦有不同来源：自然和合、信实相交、迎合索取、诱引依附。现代可反思一次交流结束后，彼此更明白了，还是只维持表面愉快。《彖传》谈使民忘劳忘死带有统治动员背景，不能直接转成管理他人情绪、诱导承担风险的技巧。相悦应允许不同意，也应保留退出空间。</p><p><strong>经传对读：</strong> 初九的和、九二的孚提供相悦的正面条件，九五却明确写“孚于剥”有厉，说明信任本身并非免检理由。上六仅两字“引兑”，没有直接占断，阅读时必须把经文未说的部分留白，再说明《小象》如何进一步评价。与巽的申命相比，兑的讲习更突出朋友间往复交流；两者都需要实际内容，不能只按声音温和或态度愉快判断是否有效。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%85%8C" target="_blank" rel="noopener noreferrer">《周易·兑》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E5%85%8C" target="_blank" rel="noopener noreferrer">《周易正义》卷六·兑</a>。</p><h2 id="gua-59" tabindex="-1">59 涣：散开阻滞，再寻共同依托 <a class="header-anchor" href="#gua-59" aria-label="Permalink to &quot;59 涣：散开阻滞，再寻共同依托 {#gua-59}&quot;">​</a></h2><p><strong>卦符：䷺｜上卦巽 ☴（风），下卦坎 ☵（水、险）。</strong> 风行水上而水面散动，涣有离散、散释之义；需要判断散的是人群，还是造成阻隔的险难。</p><p><strong>卦辞原文：</strong></p><blockquote><p>渙：亨，王假有廟，利涉大川，利貞。</p></blockquote><p><strong>白话概括：</strong> 散释困难可以通达，王建立共同祭祀依托，可渡较大险阻。《正义》区分遇难奔逃的离散与主动散难，并强调难散以后仍须以正道聚合。现代可以讨论共同目标和公共信任，但宗庙祭礼应保留其历史性质。</p><p><strong>六爻原文与简释（初六从《正义》本）：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>用拯馬壯，吉。</td><td>及早借强健马匹救援或脱险，不等局面严重再逃；独立电子页另有“悔亡”，此从古注所录。</td></tr><tr><td>九二</td><td>渙奔其机，悔亡。</td><td>在离散中奔向可支撑的几案，古注借以说明寻找依托；“机／機”指承物之具，不是机器。</td></tr><tr><td>六三</td><td>渙其躬，无悔。</td><td>不固守自身所在的险处，向外寻求相应者；常见伦理发挥为去私，原文仍有身体离散的画面。</td></tr><tr><td>六四</td><td>渙其群，元吉。渙有丘，匪夷所思。</td><td>《正义》解释为为群体散险，又须想到丘墟未平之患；另有散小群成大聚等读法，不宜把一种说法写成唯一。</td></tr><tr><td>九五</td><td>渙汗其大號，渙王居，无咎。</td><td>大号令如汗出而散布，解除困阨；《正义》另断作“渙，王居無咎”，解释为王主持涣难，须留意断句差别。</td></tr><tr><td>上九</td><td>渙其血，去逖出，无咎。</td><td>远离血伤与危害而出险；“血、逖”的训释有分歧，共同重心可从《小象》“远害”把握。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>風行水上，渙；先王以享于帝立廟。</p></blockquote><p><strong>大象解释：</strong> 在离散、散难的背景中，以祭帝立庙建立共同秩序。它说明古代礼仪的聚合作用，不证明任何特定仪式能消灾。</p><p><strong>整体读法与误区：</strong> 涣不能一律译作团体解散，也不能一律译作人心凝聚；散去阻碍与重建联系是相互关联的问题。可与萃比较：萃问怎样聚，涣问已有隔阂怎样解开。现代处理分裂时，需要说清要解除的是误会、利益封闭还是现实伤害，再讨论新的依托。若只要求“顾全大局”而抹去具体诉求，并不等于已散其难。</p><p><strong>经传对读：</strong> 明夷六二与涣初六同有“用拯马壮”，在不同卦中都把及时救助写得具体；涣九二再用几案表现可依靠之处。可见“散”并不要求一切支撑都消失。六三、六四、九五逐渐由自身推向群体与号令，而上九收回到远害，说明范围扩大之后，仍要检查具体的人是否真正脱险。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B8%99" target="_blank" rel="noopener noreferrer">《周易·涣》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/06%E6%B8%99" target="_blank" rel="noopener noreferrer">《周易正义》卷六·涣</a>。</p>',46)])])}const u=r(n,[["render",d]]);export{c as __pageData,u as default};
